test({ sr: 'vraća dužinu svake reči', en: 'returns the length of every word' }, () => {
  expect(wordLengths(['cat', 'house'])).toEqual([3, 5]);
});
test({ sr: 'prazan tekst ima dužinu 0', en: 'an empty text has length 0' }, () => {
  expect(wordLengths(['a', '', 'abc'])).toEqual([1, 0, 3]);
});
test({ sr: 'prazan niz daje prazan niz', en: 'an empty array gives an empty array' }, () => {
  expect(wordLengths([])).toEqual([]);
});

hiddenTests:
test('keeps the order of the words', () => {
  expect(wordLengths(['aaaa', 'b', 'cc'])).toEqual([4, 1, 2]);
});
test('a single word', () => {
  expect(wordLengths(['hello'])).toEqual([5]);
});
test('only empty texts', () => {
  expect(wordLengths(['', ''])).toEqual([0, 0]);
});
test('does not change the input', () => {
  const input = ['cat', 'house'];
  const result = wordLengths(input);
  expect(input).toEqual(['cat', 'house']);
  expect(result).not.toBe(input);
});

solutions.code:
function wordLengths(words) {
  const lengths = [];
  for (const word of words) {
    lengths.push(word.length);
  }
  return lengths;
}
